import type {
  AdminReferredUsersResponse,
  AdminUser,
  AdminUserChatsResponse,
  AdminUserCreditsResponse,
  AdminUserKycResponse,
  AdminUserStatsResponse,
  AdjustCreditsRequest,
  ListAdminUsersResponse,
  ListUsersParams,
  UpdateUserRequest,
} from '../types';
import type { AdminUserAccreditationResponse } from '../types/accreditation';
import type {
  AdminDepositListResponse,
  AdminUserWithdrawalHistoryResponse,
} from '../types/deposit';
import { ApiClient, handleApiError } from './apiClient';

/**
 * API client for admin user operations
 *
 * Requires system admin privileges.
 */
export class AdminUserApiClient {
  private client: ApiClient;

  constructor(
    baseUrl: string,
    timeoutMs?: number,
    retryAttempts?: number,
    getAccessToken?: () => string | null
  ) {
    this.client = new ApiClient({ baseUrl, timeoutMs, retryAttempts, getAccessToken });
  }

  /**
   * List all users in the system
   */
  async listUsers(params?: ListUsersParams): Promise<ListAdminUsersResponse> {
    try {
      const query = new URLSearchParams();
      if (params?.limit) query.set('limit', String(params.limit));
      if (params?.offset) query.set('offset', String(params.offset));
      const queryString = query.toString();
      const url = `/admin/users${queryString ? `?${queryString}` : ''}`;
      return await this.client.get<ListAdminUsersResponse>(url);
    } catch (error) {
      throw handleApiError(error, 'Failed to list users');
    }
  }

  /**
   * Get a specific user by ID
   */
  async getUser(userId: string): Promise<AdminUser> {
    try {
      return await this.client.get<AdminUser>(`/admin/users/${userId}`);
    } catch (error) {
      throw handleApiError(error, 'Failed to get user');
    }
  }

  /**
   * Set a user's system admin status
   */
  async setSystemAdmin(userId: string, isAdmin: boolean): Promise<void> {
    try {
      await this.client.patch(`/admin/users/${userId}/system-admin`, { isAdmin });
    } catch (error) {
      throw handleApiError(error, 'Failed to update system admin status');
    }
  }

  /**
   * Update a user's profile
   */
  async updateUser(userId: string, data: UpdateUserRequest): Promise<AdminUser> {
    try {
      return await this.client.patch<AdminUser>(`/admin/users/${userId}`, data);
    } catch (error) {
      throw handleApiError(error, 'Failed to update user');
    }
  }

  /**
   * Delete a user
   */
  async deleteUser(userId: string): Promise<void> {
    try {
      await this.client.delete(`/admin/users/${userId}`);
    } catch (error) {
      throw handleApiError(error, 'Failed to delete user');
    }
  }

  /**
   * Send a password reset email to a user
   */
  async forcePasswordReset(userId: string): Promise<void> {
    try {
      await this.client.post(`/admin/users/${userId}/force-password-reset`, {});
    } catch (error) {
      throw handleApiError(error, 'Failed to send password reset email');
    }
  }

  /**
   * Adjust a user's credits
   */
  async adjustCredits(userId: string, data: AdjustCreditsRequest): Promise<void> {
    try {
      await this.client.post(`/admin/users/${userId}/credits`, data);
    } catch (error) {
      throw handleApiError(error, 'Failed to adjust credits');
    }
  }

  /**
   * Get a user's deposit history
   */
  async getUserDeposits(
    userId: string,
    params?: ListUsersParams
  ): Promise<AdminDepositListResponse> {
    try {
      const query = new URLSearchParams();
      if (params?.limit) query.set('limit', String(params.limit));
      if (params?.offset) query.set('offset', String(params.offset));
      const queryString = query.toString();
      const url = `/admin/users/${userId}/deposits${queryString ? `?${queryString}` : ''}`;
      return await this.client.get<AdminDepositListResponse>(url);
    } catch (error) {
      throw handleApiError(error, 'Failed to get user deposits');
    }
  }

  /**
   * Get a user's credit stats and transaction history
   */
  async getUserCredits(
    userId: string,
    params?: ListUsersParams
  ): Promise<AdminUserCreditsResponse> {
    try {
      const query = new URLSearchParams();
      if (params?.limit) query.set('limit', String(params.limit));
      if (params?.offset) query.set('offset', String(params.offset));
      const queryString = query.toString();
      const url = `/admin/users/${userId}/credits${queryString ? `?${queryString}` : ''}`;
      return await this.client.get<AdminUserCreditsResponse>(url);
    } catch (error) {
      throw handleApiError(error, 'Failed to get user credits');
    }
  }

  /**
   * Get a user's withdrawal history
   */
  async getUserWithdrawalHistory(
    userId: string,
    params?: ListUsersParams
  ): Promise<AdminUserWithdrawalHistoryResponse> {
    try {
      const query = new URLSearchParams();
      if (params?.limit) query.set('limit', String(params.limit));
      if (params?.offset) query.set('offset', String(params.offset));
      const queryString = query.toString();
      const url = `/admin/users/${userId}/withdrawal-history${queryString ? `?${queryString}` : ''}`;
      return await this.client.get<AdminUserWithdrawalHistoryResponse>(url);
    } catch (error) {
      throw handleApiError(error, 'Failed to get user withdrawal history');
    }
  }

  /**
   * Get a user's chat history (from cedros-pay)
   * Only available when cedros-pay is enabled.
   */
  async getUserChats(userId: string, params?: ListUsersParams): Promise<AdminUserChatsResponse> {
    try {
      const query = new URLSearchParams();
      if (params?.limit) query.set('limit', String(params.limit));
      if (params?.offset) query.set('offset', String(params.offset));
      const queryString = query.toString();
      const url = `/admin/users/${userId}/chats${queryString ? `?${queryString}` : ''}`;
      return await this.client.get<AdminUserChatsResponse>(url);
    } catch (error) {
      throw handleApiError(error, 'Failed to get user chat history');
    }
  }

  /**
   * Get the list of users directly referred by a given user
   */
  async getUserReferrals(
    userId: string,
    params?: ListUsersParams
  ): Promise<AdminReferredUsersResponse> {
    try {
      const query = new URLSearchParams();
      if (params?.limit) query.set('limit', String(params.limit));
      if (params?.offset) query.set('offset', String(params.offset));
      const queryString = query.toString();
      const url = `/admin/users/${userId}/referrals${queryString ? `?${queryString}` : ''}`;
      return await this.client.get<AdminReferredUsersResponse>(url);
    } catch (error) {
      throw handleApiError(error, 'Failed to get user referrals');
    }
  }

  /**
   * Get a user's KYC status and session history
   */
  async getUserKyc(userId: string): Promise<AdminUserKycResponse> {
    try {
      return await this.client.get<AdminUserKycResponse>(`/admin/users/${userId}/kyc`);
    } catch (error) {
      throw handleApiError(error, 'Failed to get user KYC data');
    }
  }

  /**
   * Override a user's KYC status (system admin only)
   *
   * @param userId - target user ID
   * @param status - new status: "none" | "verified" | "failed"
   */
  async overrideUserKyc(userId: string, status: string): Promise<void> {
    try {
      await this.client.post(`/admin/users/${userId}/kyc/override`, { status });
    } catch (error) {
      throw handleApiError(error, 'Failed to override KYC status');
    }
  }

  /**
   * Get a user's accreditation status and submission history
   */
  async getUserAccreditation(userId: string): Promise<AdminUserAccreditationResponse> {
    try {
      return await this.client.get<AdminUserAccreditationResponse>(
        `/admin/users/${userId}/accreditation`
      );
    } catch (error) {
      throw handleApiError(error, 'Failed to get user accreditation data');
    }
  }

  /**
   * Review an accreditation submission (approve or reject).
   *
   * @param submissionId - target submission ID
   * @param approved - true to approve, false to reject
   * @param reviewerNotes - optional internal notes
   * @param rejectionReason - required when approved is false
   * @param expiryDays - override default expiry (approve only)
   */
  async reviewAccreditation(
    submissionId: string,
    approved: boolean,
    reviewerNotes?: string,
    rejectionReason?: string,
    expiryDays?: number
  ): Promise<void> {
    try {
      await this.client.post(`/admin/accreditation/${submissionId}/review`, {
        approved,
        reviewerNotes,
        rejectionReason,
        expiryDays,
      });
    } catch (error) {
      throw handleApiError(error, 'Failed to review accreditation submission');
    }
  }

  /**
   * Override a user's accreditation status (system admin only).
   *
   * @param userId - target user ID
   * @param status - new status: "none" | "approved" | "rejected"
   */
  async overrideAccreditationStatus(userId: string, status: string): Promise<void> {
    try {
      await this.client.post(`/admin/users/${userId}/accreditation/override`, { status });
    } catch (error) {
      throw handleApiError(error, 'Failed to override accreditation status');
    }
  }

  /**
   * Get user statistics by auth method
   */
  async getStats(): Promise<AdminUserStatsResponse> {
    try {
      return await this.client.get<AdminUserStatsResponse>('/admin/users/stats');
    } catch (error) {
      throw handleApiError(error, 'Failed to get user stats');
    }
  }
}
